-- Resources: the resource card, the only post type.

create table public.resources (
  id uuid primary key default gen_random_uuid(),
  -- Generated by the app from the title (Uzbek transliteration) and never changed afterwards.
  slug text not null,
  author_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  topic_id uuid not null references public.topics (id) on delete restrict,

  title text not null,
  -- Stored normalized by the app (lower-case host, no tracking parameters), so the unique
  -- constraint detects duplicates.
  url text not null,
  domain text generated always as (private.url_host(url)) stored not null,
  type public.resource_type not null,
  language public.resource_language not null,
  price public.resource_price not null,
  level public.resource_level not null,
  summary text not null,
  for_whom text not null,
  author_review text,

  status public.resource_status not null default 'pending',
  link_status public.link_status not null default 'unknown',
  -- Consecutive failed link checks; the link checker marks the link broken after two.
  link_check_failures smallint not null default 0,
  last_link_check_at timestamptz,

  -- Denormalized counters, maintained by triggers on the interaction tables only.
  likes_count integer not null default 0,
  saves_count integer not null default 0,
  comments_count integer not null default 0,
  -- Only ratings that count towards the average (see resource_ratings.counts_in_average).
  ratings_count integer not null default 0,
  ratings_sum integer not null default 0,
  popularity_score double precision not null default 0,

  -- First time the resource became published; feeds and the popularity decay use it.
  published_at timestamptz,
  created_at timestamptz not null default now(),
  -- Last edit of the card's content (not counters or moderation state).
  updated_at timestamptz not null default now(),

  search_vector tsvector generated always as (
    setweight(to_tsvector('simple'::regconfig, private.normalize_search_text(title)), 'A')
    || setweight(to_tsvector('simple'::regconfig, private.normalize_search_text(summary)), 'B')
    || setweight(to_tsvector('simple'::regconfig, private.normalize_search_text(for_whom)), 'C')
  ) stored,

  constraint resources_slug_key unique (slug),
  constraint resources_url_key unique (url),
  constraint resources_slug_format check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) <= 100),
  -- http(s), lower-case ASCII host (IDNs in punycode), optional port, no credentials, no whitespace.
  constraint resources_url_format check (
    url ~ '^https?://[a-z0-9.-]+(:[0-9]{1,5})?([/?#]|$)' and url !~ '\s' and char_length(url) <= 2048
  ),
  constraint resources_title_length check (char_length(btrim(title)) between 3 and 120),
  constraint resources_summary_length check (char_length(btrim(summary)) between 40 and 500),
  constraint resources_for_whom_length check (char_length(btrim(for_whom)) between 10 and 200),
  constraint resources_author_review_length check (char_length(btrim(author_review)) between 1 and 600),
  constraint resources_counters_non_negative check (
    likes_count >= 0 and saves_count >= 0 and comments_count >= 0 and ratings_count >= 0 and link_check_failures >= 0
  ),
  constraint resources_ratings_sum_range check (ratings_sum between ratings_count and 5 * ratings_count)
);

create index resources_author_idx on public.resources (author_id, created_at desc);
create index resources_pending_idx on public.resources (created_at) where status = 'pending';
-- "Yangi" feed and topic pages.
create index resources_published_idx on public.resources (published_at desc, id desc) where status = 'published';
create index resources_topic_published_idx on public.resources (topic_id, published_at desc)
  where status = 'published';
-- "Mashhur" feed: broken links are left out.
create index resources_popular_idx on public.resources (popularity_score desc)
  where status = 'published' and link_status <> 'broken';
-- Full-text search and typo-tolerant title search.
create index resources_search_idx on public.resources using gin (search_vector);
create index resources_title_trgm_idx on public.resources
  using gin (private.normalize_search_text(title) extensions.gin_trgm_ops);

-- ---------------------------------------------------------------------------
-- Trust: decides whether a new card is published instantly or waits for a moderator.
-- Trusted = staff, or an account at least 3 days old with 3+ published resources and no confirmed
-- (resolved) reports against its content. Everyone else goes through the pending queue.
-- ---------------------------------------------------------------------------

create function private.is_trusted_author(user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.profiles p
    where p.id = user_id
      and not p.is_banned
      and (
        p.role in ('moderator', 'admin')
        or (
          p.created_at <= now() - interval '3 days'
          and (select count(*) from public.resources r where r.author_id = p.id and r.status = 'published') >= 3
          and not exists (
            select 1 from public.reports rep
            where rep.target_owner_id = p.id and rep.status = 'resolved' and rep.target_type <> 'broken_link'
          )
        )
      )
  );
$$;

grant execute on function private.is_trusted_author(uuid) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Triggers
-- ---------------------------------------------------------------------------

create function private.prepare_resource_insert()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if private.is_blocked_domain(private.url_host(new.url)) then
    raise exception 'blocked_domain' using errcode = 'P0001', hint = 'The link''s domain is on the blocklist.';
  end if;

  -- Data API callers cannot write status or counters (column privileges); the status depends on trust.
  -- Trusted server code (imports, seeds) may insert any status.
  if current_user in ('anon', 'authenticated') then
    new.status := case when private.is_trusted_author(new.author_id) then 'published' else 'pending' end;
  end if;

  if new.status = 'published' then
    new.published_at := coalesce(new.published_at, now());
  end if;

  new.popularity_score := private.popularity_score(
    new.likes_count, new.saves_count, new.ratings_count, new.ratings_sum,
    coalesce(new.published_at, new.created_at), now()
  );
  return new;
end;
$$;

create trigger prepare_insert
  before insert on public.resources
  for each row execute function private.prepare_resource_insert();

create function private.prepare_resource_update()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  content_changed boolean :=
    (new.title, new.url, new.type, new.topic_id, new.language, new.price, new.level, new.summary, new.for_whom, new.author_review)
    is distinct from
    (old.title, old.url, old.type, old.topic_id, old.language, old.price, old.level, old.summary, old.for_whom, old.author_review);
begin
  if current_user in ('anon', 'authenticated') then
    if content_changed and old.author_id is distinct from (select auth.uid()) then
      raise exception 'Only the author can edit a resource' using errcode = '42501';
    end if;
    if (new.status, new.link_status) is distinct from (old.status, old.link_status) and not private.is_staff() then
      raise exception 'Only staff can change a resource''s status' using errcode = '42501';
    end if;
  end if;

  if new.url is distinct from old.url then
    if private.is_blocked_domain(private.url_host(new.url)) then
      raise exception 'blocked_domain' using errcode = 'P0001', hint = 'The link''s domain is on the blocklist.';
    end if;

    -- A new link must be checked again: by the link checker, and by a moderator unless the
    -- author is trusted (prevents publishing a good link and swapping it for spam later).
    new.link_status := 'unknown';
    new.link_check_failures := 0;
    new.last_link_check_at := null;
    if current_user in ('anon', 'authenticated') and new.status = 'published'
      and not private.is_trusted_author(old.author_id)
    then
      new.status := 'pending';
    end if;
  end if;

  if new.status = 'published' and new.published_at is null then
    new.published_at := now();
  end if;

  if content_changed then
    new.updated_at := now();
  end if;

  new.popularity_score := private.popularity_score(
    new.likes_count, new.saves_count, new.ratings_count, new.ratings_sum,
    coalesce(new.published_at, new.created_at), now()
  );
  return new;
end;
$$;

create trigger prepare_update
  before update on public.resources
  for each row execute function private.prepare_resource_update();

-- ---------------------------------------------------------------------------
-- Privileges and Row Level Security
-- ---------------------------------------------------------------------------

revoke all on table public.resources from anon, authenticated;
grant select on table public.resources to anon, authenticated;
grant insert (slug, topic_id, title, url, type, language, price, level, summary, for_whom, author_review),
  update (topic_id, title, url, type, language, price, level, summary, for_whom, author_review, status, link_status),
  delete
  on table public.resources to authenticated;

alter table public.resources enable row level security;

create policy "Published resources are public; authors and staff see the rest"
  on public.resources for select
  to anon, authenticated
  using (status = 'published' or author_id = (select auth.uid()) or (select private.is_staff()));

create policy "Active users can create resources"
  on public.resources for insert
  to authenticated
  with check (author_id = (select auth.uid()) and (select private.is_active_user()));

-- Authors edit content; staff change status (the update trigger enforces which columns).
create policy "Authors and staff can update resources"
  on public.resources for update
  to authenticated
  using ((author_id = (select auth.uid()) and (select private.is_active_user())) or (select private.is_staff()))
  with check ((author_id = (select auth.uid()) and (select private.is_active_user())) or (select private.is_staff()));

create policy "Authors can delete their resources"
  on public.resources for delete
  to authenticated
  using (author_id = (select auth.uid()) and (select private.is_active_user()));

revoke execute on all functions in schema private from public;
